UPDATE xsy_mall_customer_account
SET status = #{status}, version = version + 1, updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE id = #{accountId}
    AND deleted = FALSE

UPDATE xsy_mall_customer_account
SET password_hash = #{passwordHash}, first_password_change = TRUE, login_failed_count = 0, locked_until = NULL,
    version = version + 1, updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE id = #{accountId}
    AND deleted = FALSE
